begin;
drop trigger if exists cloud_generation_job_page_status on public.cloud_generation_jobs;drop function if exists public.sync_cloud_page_production_status_from_job();
drop trigger if exists cloud_character_version_production_context on public.cloud_character_profile_versions;drop trigger if exists cloud_style_version_production_context on public.cloud_style_bible_versions;drop trigger if exists cloud_world_version_production_context on public.cloud_world_profile_versions;drop trigger if exists cloud_visual_reference_production_context on public.cloud_visual_reference_assets;drop function if exists public.bump_cloud_production_context_revision();
drop function if exists public.set_cloud_page_production_status(uuid,text);drop index if exists public.cloud_pages_production_status_idx;alter table public.cloud_pages drop constraint if exists cloud_pages_production_status_check;
create or replace function public.acquire_cloud_page_edit_lock(p_page_id uuid,p_lock_token uuid,p_lease_seconds integer default 120) returns timestamptz language plpgsql security definer set search_path=public as $$declare v_page public.cloud_pages%rowtype;v_profile uuid:=public.current_profile_id();v_expires timestamptz;begin select * into v_page from public.cloud_pages where id=p_page_id and deleted_at is null;if v_page.id is null or v_profile is null or not public.cloud_project_can_edit(v_page.project_id) or p_lease_seconds not between 60 and 300 then raise exception 'cloud_page_lock_invalid';end if;insert into public.cloud_page_edit_locks(page_id,project_id,locked_by_profile_id,lock_token,lease_expires_at) values(v_page.id,v_page.project_id,v_profile,p_lock_token,now()+make_interval(secs=>p_lease_seconds)) on conflict(page_id) do update set locked_by_profile_id=excluded.locked_by_profile_id,lock_token=excluded.lock_token,lease_expires_at=excluded.lease_expires_at,updated_at=now() where public.cloud_page_edit_locks.lease_expires_at<=now() or(public.cloud_page_edit_locks.locked_by_profile_id=v_profile and public.cloud_page_edit_locks.lock_token=p_lock_token) returning lease_expires_at into v_expires;if v_expires is null then raise exception 'cloud_page_locked';end if;return v_expires;end$$;
create or replace function public.save_cloud_page_snapshot(p_page_id uuid,p_expected_revision bigint,p_canvas jsonb) returns table(page_id uuid,revision bigint,updated_at timestamptz) language plpgsql security invoker set search_path=public as $$declare v_page public.cloud_pages%rowtype;v_profile_id uuid:=public.current_profile_id();v_project_revision bigint;v_now timestamptz:=clock_timestamp();begin if v_profile_id is null or jsonb_typeof(p_canvas)<>'object' or pg_column_size(p_canvas)>2097152 then raise exception 'invalid_snapshot_input';end if;select * into v_page from public.cloud_pages where id=p_page_id for update;if not found or not public.cloud_project_can_edit(v_page.project_id) then raise exception 'page_not_found';end if;if v_page.revision<>p_expected_revision then raise exception 'revision_conflict:%',v_page.revision;end if;update public.cloud_pages set revision=cloud_pages.revision+1,updated_at=v_now where id=p_page_id returning cloud_pages.revision into revision;insert into public.cloud_canvas_snapshots(project_id,page_id,revision,canvas,created_by_profile_id,created_at) values(v_page.project_id,p_page_id,revision,p_canvas,v_profile_id,v_now);update public.cloud_projects set revision=cloud_projects.revision+1,updated_at=v_now where id=v_page.project_id returning cloud_projects.revision into v_project_revision;insert into public.cloud_project_versions(project_id,revision,manifest,created_by_profile_id,created_at) values(v_page.project_id,v_project_revision,jsonb_build_object('event','page_snapshot','pageId',p_page_id,'pageRevision',revision),v_profile_id,v_now);page_id:=p_page_id;updated_at:=v_now;return next;end$$;
alter table public.cloud_pages drop column if exists reviewed_context_revision,drop column if exists finalized_revision,drop column if exists production_status_updated_by_profile_id,drop column if exists production_status_updated_at,drop column if exists production_status;alter table public.cloud_projects drop column if exists production_context_revision;
commit;
